/** Offline composition only. Reads reviewed Git blobs and independently pinned inputs. */
import {spawnSync} from 'node:child_process';
import {mkdir,writeFile,realpath,lstat} from 'node:fs/promises';
import {dirname,isAbsolute,join,relative,resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
import {archiveHostHash,archiveHostRead,parseArchiveRuntime,verifyArchiveTree,copyArchiveFiles} from './archive-host-package.mjs';
import {IMAGE_PREPARATION_HOST_SOURCE_FILES,imagePreparationHostFailure,parseImagePreparationServiceBundle,parseImagePreparationHostBundle} from './image-preparation-host-package.mjs';
function git(root,args){const r=spawnSync('git',['-c','safe.directory='+root,'-C',root,...args],{shell:false,encoding:null,maxBuffer:32*1024**2,timeout:30000,env:{PATH:process.env.PATH,SYSTEMROOT:process.env.SYSTEMROOT,LANG:'C',LC_ALL:'C',GIT_NO_REPLACE_OBJECTS:'1',GIT_CONFIG_NOSYSTEM:'1',GIT_CONFIG_GLOBAL:process.platform==='win32'?'NUL':'/dev/null'}});if(r.status!==0||r.error)imagePreparationHostFailure();return r.stdout;}
export async function buildImagePreparationHostBundle({sourceRoot,commit,runtimeRoot,runtimeManifestSha256,workerBundlePath,workerBundleSha256,qualifierBundlePath,qualifierBundleSha256,output}){
 if(!/^[a-f0-9]{40}$/.test(commit)||[runtimeManifestSha256,workerBundleSha256,qualifierBundleSha256].some(s=>typeof s!=='string'||!/^[a-f0-9]{64}$/.test(s)))imagePreparationHostFailure();
 const root=await realpath(sourceRoot),runtimePath=await realpath(runtimeRoot),workerPath=await realpath(workerBundlePath),qualifierPath=await realpath(qualifierBundlePath),target=resolve(output),within=base=>{const rel=relative(base,target);return rel===''||!isAbsolute(rel)&&rel!=='..'&&!rel.startsWith('..\\')&&!rel.startsWith('../');};if([root,runtimePath,workerPath,qualifierPath].some(within))imagePreparationHostFailure();
 const runtimeBytes=await archiveHostRead(join(runtimePath,'runtime-manifest.json'));if(archiveHostHash(runtimeBytes)!==runtimeManifestSha256)imagePreparationHostFailure();const originalRuntime=parseArchiveRuntime(JSON.parse(runtimeBytes));await verifyArchiveTree(runtimePath,originalRuntime.files,{extra:['runtime-manifest.json'],emptyDirectories:originalRuntime.emptyDirectories});
 if(git(root,['rev-parse','--verify',commit+'^{commit}']).toString().trim()!==commit)imagePreparationHostFailure();const tree=git(root,['rev-parse',commit+'^{tree}']).toString().trim(),treeEntries=new Map(git(root,['ls-tree','-r',commit]).toString().trim().split('\n').filter(Boolean).map(line=>{const at=line.indexOf('\t');return [line.slice(at+1),line.slice(0,at)];}));
 const source=path=>{if(!/^100(?:644|755) blob [a-f0-9]{40}$/.test(treeEntries.get(path)??''))imagePreparationHostFailure();return git(root,['show',commit+':'+path]);};
 const lock=source('package-lock.json');if(archiveHostHash(lock)!==originalRuntime.packageLockSha256)imagePreparationHostFailure();const lockObject=JSON.parse(lock),parts={};
 for(const [name,service,path,digest]of [['worker','image-preparation',workerPath,workerBundleSha256],['qualifier','image-preparation-qualification',qualifierPath,qualifierBundleSha256]]){
  const raw=await archiveHostRead(join(path,'bundle.json'));if(archiveHostHash(raw)!==digest)imagePreparationHostFailure();const bundle=parseImagePreparationServiceBundle(JSON.parse(raw),service);if(!raw.equals(Buffer.from(JSON.stringify(bundle,null,2)+'\n'))||bundle.sourceCommit!==commit||bundle.sourceTree!==tree||bundle.packageLockSha256!==originalRuntime.packageLockSha256||lockObject.packages?.['node_modules/esbuild']?.version!==bundle.compiler.version||lockObject.packages?.['node_modules/esbuild']?.integrity!==bundle.compiler.packageIntegrity)imagePreparationHostFailure();
  await verifyArchiveTree(path,[{...bundle.runtime,mode:0o444}],{extra:['bundle.json']});
  for(const input of bundle.inputs){if(input.kind==='source'){const bytes=source(input.path);if(bytes.length!==input.bytes||archiveHostHash(bytes)!==input.sha256)imagePreparationHostFailure();}else{const entry=originalRuntime.files.find(f=>f.path===input.path);if(!entry||entry.bytes!==input.bytes||entry.sha256!==input.sha256)imagePreparationHostFailure();}}
  parts[name]={bundleSha256:digest,bundle};
 }
 const sources=new Set([...IMAGE_PREPARATION_HOST_SOURCE_FILES,...parts.worker.bundle.inputs.filter(i=>i.kind==='source').map(i=>i.path),...parts.qualifier.bundle.inputs.filter(i=>i.kind==='source').map(i=>i.path)]),sourceBytes=new Map();for(const path of sources)sourceBytes.set(path,path==='package-lock.json'?lock:source(path));
 if(archiveHostHash(sourceBytes.get('scripts/hosting/media-sandbox-launch.c'))!==originalRuntime.sourceHashes.launcher||archiveHostHash(sourceBytes.get('scripts/hosting/media-sandbox-probe.c'))!==originalRuntime.sourceHashes.probe)imagePreparationHostFailure();
 const parent=dirname(target);if(await realpath(parent)!==parent||!(await lstat(parent)).isDirectory())imagePreparationHostFailure();await mkdir(target,{mode:0o755});const files=[];
 for(const [path,bytes]of sourceBytes){const destination=join(target,'source',path);await mkdir(dirname(destination),{recursive:true,mode:0o755});await writeFile(destination,bytes,{flag:'wx',mode:0o444});files.push({path:'source/'+path,bytes:bytes.length,sha256:archiveHostHash(bytes),mode:0o444});}
 const runtime={...originalRuntime,files:originalRuntime.files.filter(f=>!f.path.startsWith('node_modules/'))};await mkdir(join(target,'runtime'),{mode:0o755});await copyArchiveFiles(runtimePath,join(target,'runtime'),runtime.files,{emptyDirectories:runtime.emptyDirectories});files.push(...runtime.files.map(f=>({...f,path:'runtime/'+f.path})));
 for(const [name,path]of [['worker',workerPath],['qualifier',qualifierPath]]){const part=parts[name],raw=await archiveHostRead(join(path,'bundle.json'));await mkdir(join(target,name),{mode:0o755});await copyArchiveFiles(path,join(target,name),[{...part.bundle.runtime,mode:0o444}]);if(archiveHostHash(raw)!==part.bundleSha256)imagePreparationHostFailure();await writeFile(join(target,name,'bundle.json'),raw,{flag:'wx',mode:0o444});files.push({...part.bundle.runtime,path:name+'/runtime.mjs',mode:0o444},{path:name+'/bundle.json',bytes:raw.length,sha256:part.bundleSha256,mode:0o444});}
 files.sort((a,b)=>a.path.localeCompare(b.path,'en'));const bundle=parseImagePreparationHostBundle({version:1,kind:'coatria-image-preparation-host',commit,tree,runtimeInputSha256:runtimeManifestSha256,runtime,...parts,files,emptyDirectories:runtime.emptyDirectories.map(d=>({...d,path:'runtime/'+d.path}))}),raw=JSON.stringify(bundle,null,2)+'\n';await writeFile(join(target,'bundle.json'),raw,{flag:'wx',mode:0o444});await verifyArchiveTree(target,files,{extra:['bundle.json'],emptyDirectories:bundle.emptyDirectories});return {commit,tree,bundleSha256:archiveHostHash(raw),runtimeInputSha256:runtimeManifestSha256,output:target,qualified:false,servicesEnabled:false,providerCalls:false};
}
if(process.argv[1]&&import.meta.url===pathToFileURL(resolve(process.argv[1])).href)void(async()=>{try{const[sourceRoot,commit,runtimeRoot,runtimeManifestSha256,workerBundlePath,workerBundleSha256,qualifierBundlePath,qualifierBundleSha256,output,...extra]=process.argv.slice(2);if(!output||extra.length)imagePreparationHostFailure();console.log(JSON.stringify(await buildImagePreparationHostBundle({sourceRoot,commit,runtimeRoot,runtimeManifestSha256,workerBundlePath,workerBundleSha256,qualifierBundlePath,qualifierBundleSha256,output})));}catch{console.error('IMAGE_PREPARATION_HOST_BUILD_REJECTED');process.exitCode=1;}})();
